suppressPackageStartupMessages({library(ggplot2);library(ggrastr);library(patchwork)})
md<-qread(out('00_audit/cell_metadata.qs'));ss<-fread(out('01_score_comparison/cluster_score_summaries.tsv'));tests<-fread(out('01_score_comparison/paired_tests.tsv'));pairs<-fread(out('01_score_comparison/sample_pairs.tsv'));pr<-fread(out('04_14MP_profiles/profiles_long.tsv'));cov<-fread(out('03_sample_robustness/composition_coverage_all_levels.tsv'));dots<-fread(out('06_supplement/RNA_DotPlot_data.tsv'));pan<-fread(out('06_supplement/fixed_panel_all_models.tsv'));blue<-'#173B75';scopes<-c('ALL',sort(unique(md$dataset)));idx<-list()
th<-theme_classic(base_size=10)+theme(plot.background=element_rect(fill='transparent',colour=NA),panel.background=element_rect(fill='transparent',colour=NA),legend.background=element_rect(fill='transparent',colour=NA),legend.box.background=element_rect(fill='transparent',colour=NA),strip.background=element_blank(),panel.grid=element_blank())
basecap<-'K32 denotes C18 in the frozen FULL_Z_r1.00 partition, not an NMF rank. All results characterize a selected candidate within the same discovery data and are not independent validation.'
savep<-function(p,name,data,w=10,h=6,caption=''){fn<-out(name);dir.create(dirname(fn),recursive=TRUE,showWarnings=FALSE);if(!file.exists(paste0(fn,'.pdf'))||grepl('violin|^05_umap',name)){ggsave(paste0(fn,'.pdf'),p,width=w,height=h,bg='transparent',limitsize=FALSE);ggsave(paste0(fn,'.png'),p,width=w,height=h,dpi=300,bg='transparent',limitsize=FALSE)};if(is.character(data)&&length(data)==1){dp<-data}else{dp<-paste0(name,'_plotdata.tsv.gz');wt(data,dp)};idx[[length(idx)+1L]]<<-data.table(figure=basename(name),pdf=paste0(name,'.pdf'),png=paste0(name,'.png'),plot_data=dp,caption=paste(caption,basecap));wt(rbindlist(idx),'06_supplement/figure_index.tsv');logmsg('Figure',name)}
for(br in c('full','exclude_P07T'))for(s in c('UCell','NMF')){d<-if(br=='full')copy(md)else md[sample!=excluded_sample];sum<-ss[branch==br&score==s][order(rank)];lev<-sum$cluster;field<-if(s=='UCell')'ucell10'else'usage10';d[,`:=`(plot_value=if(s=='UCell')get(field)else log1p(get(field)),cl=factor(cluster,levels=lev))];sum[,`:=`(cl=factor(cluster,levels=lev),mean_plot=if(s=='UCell')mean else log1p(mean),median_plot=if(s=='UCell')median else log1p(median),K32=cluster=='C18')];t<-tests[branch==br&score==s];y<-max(d$plot_value)*1.06;cx<-match(c('C18',t$control),lev);lab<-paste0(if(is.finite(t$p_Holm)&&t$p_Holm<.05)'*  'else'', 'paired Holm p = ',format(t$p_Holm,digits=4));p<-ggplot(d,aes(cl,plot_value,fill=K32))+geom_violin(scale='width',trim=TRUE,linewidth=.2)+scale_fill_manual(values=c('FALSE'='grey80','TRUE'=blue),guide='none')+geom_point(data=sum,aes(cl,median_plot,shape='Median'),inherit.aes=FALSE,size=1.7,colour='black')+geom_point(data=sum,aes(cl,mean_plot,shape='Mean (raw scale)'),inherit.aes=FALSE,size=2.2,colour='#C33B24')+scale_shape_manual(values=c('Median'=16,'Mean (raw scale)'=18),name=NULL)+annotate('segment',x=min(cx),xend=max(cx),y=y,yend=y,linewidth=.35)+annotate('text',x=min(cx),y=y*1.035,label=lab,size=3,hjust=0)+scale_x_discrete(labels=setNames(paste0(sum$cluster,'\nn=',sum$n),sum$cluster))+labs(x='Clusters ordered by raw-score mean',y=if(s=='UCell')'MP10 UCell (raw)'else'log1p(MP10 NMF usage raw)')+th+theme(axis.text.x=element_text(angle=90,hjust=1,vjust=.5,size=7),legend.position='top');savep(p,paste0('01_score_comparison/',br,'_',s,'_27cluster_violin'),sum,14,5.5,paste('Equal-width violins retain every cell and exact zero. Black circles: median; red diamonds: raw-score mean, displayed at log1p(mean(raw usage)) for NMF. Cell counts are printed under each cluster. Stars require Holm-adjusted p<0.05 from the two prespecified sample-paired two-sided Wilcoxon tests, never cell-level tests. Branch:',br,'; see sample_pairs.tsv and paired_tests.tsv.'))
 q<-pairs[branch==br&score==s&eligible==TRUE];a<-rbind(q[,.(sample,dataset,group='K32/C18',value=K32_mean)],q[,.(sample,dataset,group=paste0('Control/',control),value=control_mean)]);a[,group:=factor(group,levels=c(paste0('Control/',t$control),'K32/C18'))];p<-ggplot(a,aes(group,value,group=sample,colour=dataset))+geom_line(linewidth=.5,alpha=.7)+geom_point(size=2.1)+labs(x=NULL,y=if(s=='UCell')'Sample mean MP10 UCell'else'Sample mean MP10 NMF usage (raw)',colour='Dataset',subtitle=paste0('Pairs = ',t$n_pairs,'; K32 higher = ',t$n_K32_higher,'; Holm p = ',format(t$p_Holm,digits=4)))+th;savep(p,paste0('01_score_comparison/',br,'_',s,'_sample_pairs'),a,7,5,paste('Only samples with >=30 cells on each side. Each line is a biological specimen; not a confirmed independent patient. Both plotted sample means and the test use untransformed scores. Exact two-sided Wilcoxon with no ties or zero differences; Holm across UCell and NMF tests within this branch. Branch:',br))}
# Complete 27x14 matrices use frozen FULL column scaling; shared limits across branches.
clorder<-ss[branch=='full'&score=='UCell'][order(rank),cluster]
for(typ in c('raw','frozen_Z')){lims<-range(pr[branch=='full'&scale==typ,mean]);if(typ=='frozen_Z')lims<-c(-1,1)*max(abs(lims));for(br in c('full','exclude_P07T')){d<-pr[branch==br&scale==typ];d[,`:=`(MP=factor(MP,levels=mp),cluster=factor(cluster,levels=rev(clorder)))];p<-ggplot(d,aes(MP,cluster,fill=mean))+geom_tile()+geom_tile(data=d[cluster=='C18'],fill=NA,colour=blue,linewidth=.6)+scale_y_discrete(labels=function(x)ifelse(x=='C18','C18 / K32',x))+labs(x=NULL,y=NULL)+th+theme(axis.text.x=element_text(angle=45,hjust=1));if(typ=='raw')p<-p+scale_fill_viridis_c(option='plasma',limits=lims,name='Mean UCell (raw)')else p<-p+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',midpoint=0,limits=lims,name='Mean frozen global Z');savep(p,paste0('04_14MP_profiles/',br,'_',typ,'_heatmap'),d,10,10,'All 14 programs in fixed numerical order. Rows follow FULL MP10 UCell mean rank. Cell-level Z uses the original FULL mean/SD, then is averaged; cluster means are not re-standardized. Limits are shared with FULL. Z=0 is the overall reference, not absent expression.') }}
kp<-pr[cluster=='C18'&scale=='frozen_Z'];p<-ggplot(kp,aes(MP,mean,group=branch,colour=branch))+geom_hline(yintercept=0,colour='grey70')+geom_line()+geom_point()+labs(x=NULL,y='K32 mean frozen global Z',colour='Population')+th+theme(axis.text.x=element_text(angle=45,hjust=1));savep(p,'04_14MP_profiles/K32_full_exclude_profile',kp,10,4,'Full and exclude_P07T retain identical score definitions and global Z parameters. Program Z reflects relative deviation within each program, not absolute metabolic activity or mechanistic dominance.')
# Top20 are all positive-effect genes ranked by FDR, PValue, then ID; no function/FDR prefilter.
for(br in c('full','exclude_P07T'))for(ctrl in c('rest','C14')){a<-dots[branch==br&control==ctrl&dataset=='ALL'&!is.na(up_rank)&up_rank<=20];setorder(a,up_rank);lev<-a$gene_id;d<-rbind(a[,.(gene_id,group='K32',expression=expr_left,detection=pct_left,in_any_14MP_top50,n_pairs)],a[,.(gene_id,group=ctrl,expression=expr_right,detection=pct_right,in_any_14MP_top50,n_pairs)]);d[,gene_id:=factor(gene_id,levels=rev(lev))];lbl<-setNames(paste0(lev,ifelse(a$in_any_14MP_top50,' [input]','')),lev);p<-ggplot(d,aes(group,gene_id,size=detection,colour=expression))+geom_point()+scale_colour_viridis_c(option='plasma',name='Mean log-normalized RNA')+scale_size_continuous(range=c(.4,6),limits=c(0,1),name='Mean detection fraction')+scale_y_discrete(labels=lbl)+labs(x=NULL,y=NULL)+th;savep(p,paste0('06_supplement/',br,'_',ctrl,'_top20_DotPlot'),d,9,8,paste('Complete top20 under fixed positive-effect FDR/PValue/gene-ID ranking; not a significant-only or lipid-selected list. Color is the equal-weight average of eligible sample mean LogNormalize RNA (scale factor10000); dot area encodes equal-weight detection fraction across those same samples. [input] means a member of a frozen 14MP top50 signature. Model:',br,ctrl,'; eligible pairs:',unique(a$n_pairs),'; see eligibility and model summary for dataset sources and reuse/new status.'))}
for(br in c('full','exclude_P07T')){a<-pan[branch==br];p<-ggplot(a,aes(control,gene_requested,fill=log2FC))+geom_tile()+geom_text(aes(label=ifelse(!tested,'NT',ifelse(FDR<.05,'*',''))),size=4)+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',midpoint=0,limits=c(-1,1)*max(abs(pan$log2FC),na.rm=TRUE),name='K32 minus control log2FC',na.value='grey80')+labs(x=NULL,y=NULL)+th;savep(p,paste0('06_supplement/',br,'_fixed_panel_effects'),a,8,6,'Prespecified gene panel, independent of top20 rank. * denotes within-model BH-FDR<0.05; NT means not tested, never no difference. Every full effect/FDR/detection/direction/input-membership value is retained in fixed_panel_all_models.tsv. No multiplicity claim across candidate selection or models.')}
sm<-unique(md[,.(sample,dataset,source)]);setorder(sm,dataset,sample);sm[,sample_code:=sprintf('S%02d',.I)];wt(sm,'03_sample_robustness/sample_display_key.tsv')
for(br in c('full','exclude_P07T')){a<-merge(cov[branch==br&level=='sample'],sm,by.x='unit',by.y='sample');p<-ggplot(a,aes(reorder(sample_code,-contribution),contribution,fill=dataset))+geom_col()+labs(x='Specimens (sample_display_key.tsv)',y='Contribution to K32',fill='Dataset')+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6));savep(p,paste0('03_sample_robustness/',br,'_sample_contribution'),a,13,4,'Contribution denominator is all K32 cells in the corresponding population; every retained specimen, including zero K32, is shown. P07T exclusion uses the exact manifest sample ID, retaining P07N.')
 d<-melt(a,id.vars=c('sample_code','unit','dataset'),measure.vars=c('NMFprecision','NMFrecall','UCellprecision','UCellrecall'),variable.name='metric');p<-ggplot(d,aes(sample_code,metric,fill=value))+geom_tile()+scale_fill_viridis_c(option='plasma',limits=c(0,1),na.value='grey80',name='Fraction')+labs(x='All retained specimens',y=NULL)+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6));savep(p,paste0('03_sample_robustness/',br,'_sample_precision_recall'),d,13,4,'Frozen high labels and thresholds; denominators use the retained population. Candidate=0 gives precision NA; high=0 gives recall NA; high>0 with no candidate gives recall0. No >=30-cell eligibility filter is applied to coverage.')}
# Frozen UMAPs: shared limits, complete point set, ascending positive-score overplot order.
limits<-list(ucell10=range(md$ucell10),usage_log1p=range(log1p(md$usage10)));wt(data.table(score=names(limits),lower=sapply(limits,min),upper=sapply(limits,max)),'05_umap/continuous_color_limits.tsv')
for(em in c('FULL_Z','RNA')){d<-fread(out(paste0('05_umap/',em,'_plot_data.tsv.gz')));xl<-range(d$x);yl<-range(d$y)
 for(ds in scopes){a<-if(ds=='ALL')copy(d)else d[dataset==ds];pp<-list();for(v in names(limits)){z<-copy(a);setorderv(z,c(v,'cell_id'));p<-ggplot(z,aes(x,y))+geom_point_rast(data=z[get(v)==0],aes(shape='Exact zero'),colour='black',size=.13,raster.dpi=300,show.legend=TRUE)+geom_point_rast(data=z[get(v)>0],aes(colour=.data[[v]]),size=.13,raster.dpi=300)+geom_point_rast(data=z[is.na(get(v))],aes(shape='Missing (none)'),colour='#00BFC4',size=.13,raster.dpi=300,show.legend=TRUE)+scale_shape_manual(values=c('Exact zero'=16,'Missing (none)'=4),limits=c('Exact zero','Missing (none)'),name=NULL,drop=FALSE)+guides(shape=guide_legend(override.aes=list(size=2,colour=c('black','#00BFC4'))))+scale_colour_viridis_c(option='plasma',limits=limits[[v]],name=if(v=='ucell10')'MP10 UCell (raw)'else'log1p MP10 usage')+coord_cartesian(xlim=xl,ylim=yl)+labs(x=paste(em,'UMAP 1'),y=paste(em,'UMAP 2'))+th;pp[[v]]<-p;if(ds=='ALL')savep(p,paste0('05_umap/ALL/',em,'_',v),paste0('05_umap/',em,'_plot_data.tsv.gz'),6,5,'Frozen coordinates. Exact zero is black; NA would be cyan crosses (none observed). Positive-score points are drawn in ascending score order; continuous scales retain the full global range. Original NMF usage is displayed log1p but all usage statistics/tests use raw values.')}
 a[,highlight:=factor(ifelse(K32,'K32 / C18','Other epithelial cells'),levels=c('Other epithelial cells','K32 / C18'))];setorder(a,K32,cell_id);p<-ggplot(a,aes(x,y,colour=highlight))+geom_point_rast(size=.13,raster.dpi=300)+scale_colour_manual(values=c('Other epithelial cells'='grey80','K32 / C18'=blue),drop=FALSE,name=NULL)+coord_cartesian(xlim=xl,ylim=yl)+labs(x=paste(em,'UMAP 1'),y=paste(em,'UMAP 2'))+th;pp[['highlight']]<-p;if(ds=='ALL')savep(p,paste0('05_umap/ALL/',em,'_K32_highlight'),paste0('05_umap/',em,'_plot_data.tsv.gz'),7,5,'Frozen coordinates; grey background drawn first and K32 last using exactly equal point size. No embedding fit or clustering was performed in v4.')
 p<-wrap_plots(pp,ncol=3)+plot_annotation(theme=theme(plot.background=element_rect(fill='transparent',colour=NA)));dp<-paste0('05_umap/',if(ds=='ALL')'ALL'else'by_dataset','/',em,'_',ds,'_plot_data.tsv.gz');wt(a,dp);savep(p,paste0('05_umap/',if(ds=='ALL')'ALL'else'by_dataset','/',em,'_',ds,'_triptych'),dp,18,5,paste('Identical cell IDs and coordinates across three panels. Dataset:',ds,'; n=',nrow(a),'; K32 n=',sum(a$K32),'. Global coordinate and color limits are retained for every dataset. UCell and log1p raw NMF usage use plasma; exact0 black, missing cyan (none). Ascending-score layering; equal-size grey-first K32-last highlights. Dispersed RNA locations are preserved.'))
